command:
python3 -I - <<'EOF'
import csv, json, sys
csv.field_size_limit(sys.maxsize)
hits = []
for r in csv.DictReader(open('derived/DC01/DC01-evtxecmd.csv', encoding='utf-8-sig')):
    if r['Channel'] == 'Security' and r['EventId'] == '4625':
        d = (json.loads(r['Payload']).get('EventData') or {}).get('Data') or []
        d = d if isinstance(d, list) else [d]
        f = {x.get('@Name'): x.get('#text') for x in d if isinstance(x, dict)}
        if f.get('WorkstationName') == 'kali':
            hits.append((r['EventRecordId'], r['TimeCreated'], f.get('WorkstationName'), f.get('IpAddress')))
for h in hits[:3]:
    print(*h, sep=' | ')
EOF

